// Fichas do Bestiário de Arton, na ordem do apêndice Criaturas por ND.
function source(bookPage, bookPageEnd = bookPage) {
  const pdfOffset = 4;
  return {
    book: "Bestiário de Arton",
    edition: "1ª edição, novembro de 2026 · v1.0",
    pdfFile: "T20 Bestiario de Arton.pdf",
    bookPage,
    pdfPage: bookPage + pdfOffset,
    ...(bookPageEnd === bookPage ? {} : { bookPageEnd, pdfPageEnd: bookPageEnd + pdfOffset })
  };
}

